{
  "sql": "SELECT s.system_id, s.system_name, s.vendor, s.agency, s.data_classification, s.hipaa_relevant, COUNT(ga.assessment_id) as total_assessments, SUM(CASE WHEN ga.status = 'compliant' THEN 1 ELSE 0 END) as compliant_count, SUM(CASE WHEN ga.status = 'gap' THEN 1 ELSE 0 END) as gap_count, SUM(CASE WHEN ga.status = 'partial' THEN 1 ELSE 0 END) as partial_count, SUM(CASE WHEN ga.severity = 'critical' AND ga.status != 'compliant' THEN 1 ELSE 0 END) as critical_gaps, SUM(ga.estimated_effort_days) as total_effort_days FROM ai_systems s LEFT JOIN gap_assessments ga ON s.system_id = ga.system_id WHERE s.status = 'active' GROUP BY s.system_id, s.system_name, s.vendor, s.agency, s.data_classification, s.hipaa_relevant ORDER BY critical_gaps DESC"
}

{
  "sql": "SELECT l.license_id, s.system_name, l.total_seats, l.assigned_seats, l.active_seats, (l.assigned_seats - l.active_seats) as unused_seats, l.cost_per_seat, ROUND((l.assigned_seats - l.active_seats) * l.cost_per_seat, 2) as monthly_waste, l.hipaa_tier, l.o365_restricted, ut.credit_consumed, ut.credit_limit, ROUND(ut.credit_consumed / ut.credit_limit * 100, 1) as utilization_pct FROM licenses l JOIN ai_systems s ON l.system_id = s.system_id LEFT JOIN usage_tracking ut ON l.license_id = ut.license_id AND ut.month = (SELECT MAX(month) FROM usage_tracking) ORDER BY monthly_waste DESC"
}

