const compliance = $('Query Compliance Status').first()?.json?.rows || [];
const licenses = $('Query License Status').first()?.json?.rows || [];

const today = new Date().toISOString().split('T')[0];
const monthName = new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

// Compliance summary
const totalSystems = compliance.length;
const criticalSystems = compliance.filter(s => s.critical_gaps > 0).length;
const hipaaSystems = compliance.filter(s => s.hipaa_relevant).length;
const totalGaps = compliance.reduce((sum, s) => sum + (s.gap_count || 0), 0);
const totalPartial = compliance.reduce((sum, s) => sum + (s.partial_count || 0), 0);
const totalCompliant = compliance.reduce((sum, s) => sum + (s.compliant_count || 0), 0);
const totalEffort = compliance.reduce((sum, s) => sum + (s.total_effort_days || 0), 0);

// License summary
const totalSeats = licenses.reduce((sum, l) => sum + (l.total_seats || 0), 0);
const totalUnused = licenses.reduce((sum, l) => sum + (l.unused_seats || 0), 0);
const totalWaste = licenses.reduce((sum, l) => sum + (l.monthly_waste || 0), 0);
const overBudget = licenses.filter(l => l.utilization_pct > 85).length;

let report = `# 12th House AI — Monthly Compliance Report\n`;
report += `## ${monthName}\n\n`;
report += `---\n\n`;

report += `## Executive Summary\n\n`;
report += `| Metric | Value |\n|--------|-------|\n`;
report += `| Active AI Systems | ${totalSystems} |\n`;
report += `| Systems with Critical Gaps | ${criticalSystems} |\n`;
report += `| HIPAA-Relevant Systems | ${hipaaSystems} |\n`;
report += `| Open Gaps | ${totalGaps} |\n`;
report += `| Partial Compliance | ${totalPartial} |\n`;
report += `| Fully Compliant Items | ${totalCompliant} |\n`;
report += `| Total Remediation Effort | ${totalEffort} days |\n`;
report += `| Total License Seats | ${totalSeats.toLocaleString()} |\n`;
report += `| Unused/Reclaimable Seats | ${totalUnused.toLocaleString()} |\n`;
report += `| Monthly License Waste | $${totalWaste.toLocaleString()} |\n`;
report += `| Systems Over 85% Budget | ${overBudget} |\n\n`;

report += `## System-by-System Compliance Status\n\n`;
for (const sys of compliance) {
  const status = sys.critical_gaps > 0 ? 'CRITICAL' : sys.gap_count > 0 ? 'GAPS' : 'COMPLIANT';
  const hipaa = sys.hipaa_relevant ? ' [HIPAA]' : '';
  report += `### ${sys.system_name} (${sys.vendor})${hipaa}\n`;
  report += `- Agency: ${sys.agency} | Classification: ${sys.data_classification}\n`;
  report += `- Status: **${status}** — ${sys.compliant_count} compliant, ${sys.partial_count} partial, ${sys.gap_count} gaps (${sys.critical_gaps} critical)\n`;
  report += `- Remediation effort: ${sys.total_effort_days} days\n\n`;
}

report += `## License Governance\n\n`;
for (const lic of licenses) {
  const flag = lic.utilization_pct > 85 ? ' ⚠️ OVER BUDGET' : '';
  report += `- **${lic.system_name}**: ${lic.active_seats}/${lic.total_seats} active, ${lic.unused_seats} reclaimable ($${lic.monthly_waste}/mo)${flag}\n`;
}

report += `\n---\n`;
report += `*Generated by 12th House AI Compliance Agent on ${today}*\n`;

return [{
  json: {
    report: report,
    subject: `12th House AI — ${monthName} Compliance Report (${criticalSystems} critical, $${totalWaste.toLocaleString()} reclaimable)`,
    critical_systems: criticalSystems,
    total_waste: totalWaste
  }
}];
